rules.rules:
rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    // Reglas para Mapas Compartidos
    match /sharedMaps/{mapId} {
        allow read;
        allow create;
        allow update, delete: if false;
    }

    // Reglas para Mapas de Usuario
    match /userMaps/{mapId} {
        // Solo el dueño puede leer, actualizar o borrar sus mapas
        allow read, update, delete: if request.auth != null && request.auth.uid == resource.data.userId;
        // Cualquier usuario autenticado puede crear un mapa siempre que se asigne a su UID
        allow create: if request.auth != null && request.resource.data.userId == request.auth.uid;
    }

    match /{document=**} {
      allow read, write: if false;
    }
  }
}
